    topics = payload["topics"]
    papers = payload["papers"]
    rows = []
    for topic in topics:
        row = {}
        for paper in papers:
            methods = set(paper["methods"])
            best = None
            for claim in paper["claims"]:
                c_topic, c_section, c_quality = claim
                if c_topic == topic and c_section in methods:
                    if best is None or c_quality > best:
                        best = c_quality
            if best is not None:
                row[paper["id"]] = best
        rows.append(row)
    return rows

def combine(payload, left, right):
    """Combine the two component JSON values under the business contract in TASK.md."""
    topics = payload["topics"]
    papers = payload["papers"]

    # left: per-topic score table (list of dicts mapping paper id -> max quality)
    # right: deduped, sorted existing graph triples
    if not topics:
        return {"review": [], "graph": right}

    # Build candidate options per topic: list of (paper_id, quality)
    options = []
    for topic_scores in left:
        opts = sorted(topic_scores.items(), key=lambda kv: kv[0])
        options.append(opts)

    # Lexicographic search over assignments maximizing (min quality, total quality),
    # then lexicographically smallest paper-id sequence.
    n = len(topics)
    best = None  # (min_q, total_q, id_tuple)

    def search(i, used, chosen, min_q, total_q):
        nonlocal best
        if i == n:
            key = (min_q, total_q, tuple(chosen))
            if best is None or key > best:
                best = key
            return
        for pid, q in options[i]:
            if pid in used:
                continue
            used.add(pid)
            chosen.append(pid)
            search(i + 1, used, chosen, min(min_q, q), total_q + q)
            chosen.pop()
            used.remove(pid)

    search(0, set(), [], float("inf"), 0)

    if best is None:
        return None

    min_q, total_q, id_tuple = best
    review = [[topics[i], id_tuple[i], None] for i in range(n)]
    # Recover quality for each chosen paper
    for i in range(n):
        for pid, q in options[i]:
            if pid == id_tuple[i]:
                review[i][2] = q
                break

    # Build graph: existing edges + supports edges, dedup, sort lexicographically
    edges = set()
    for triple in right:
        edges.add(tuple(triple))
    for i in range(n):
        edges.add((id_tuple[i], "supports", topics[i]))
    graph = sorted(edges)

    return {"review": review, "graph": [list(t) for t in graph]}

