import json
import unittest
from pathlib import Path

import integration


def load(name):
    return json.loads(Path(name).read_text(encoding="utf-8"))


class TestCombine(unittest.TestCase):
    def test_public_example(self):
        payload = load("public_input.json")
        left = load("components/evidence_scores/expected.json")
        right = load("components/graph_facts/expected.json")
        result = integration.combine(payload, left, right)
        expected = load("public_expected.json")
        self.assertEqual(result, expected)

    def test_empty_topics(self):
        payload = {"topics": [], "papers": [], "graph": [["a", "r", "b"]]}
        result = integration.combine(payload, [], [["a", "r", "b"]])
        self.assertEqual(result, {"review": [], "graph": [["a", "r", "b"]]})

    def test_no_complete_assignment_returns_none(self):
        payload = {"topics": ["t1", "t2"], "papers": []}
        left = [{}, {}]
        result = integration.combine(payload, left, [])
        self.assertIsNone(result)

    def test_lexicographic_min_id_sequence(self):
        # Two topics, two papers; both papers can cover both topics with equal
        # quality, so the lexicographically smallest id sequence wins.
        payload = {"topics": ["t1", "t2"], "papers": []}
        left = [{"pA": 5, "pB": 5}, {"pA": 5, "pB": 5}]
        result = integration.combine(payload, left, [])
        self.assertEqual(result["review"], [["t1", "pA", 5], ["t2", "pB", 5]])


if __name__ == "__main__":
    unittest.main()

